test("claim tags scenario 2", { tag: '@functionality' }, async ({ browser }) => {
  const sheet = ui.sheetId();
  const pg_uma = await ui.userPage(browser, "uma", sheet);
  await ui.setToday(pg_uma, "2026-03-10");
  expect(await ui.setRole(pg_uma, "wes", "steward")).toBe(true);
  await ui.setSetting(pg_uma, "clerk-limit", "1.50");
  await ui.setSetting(pg_uma, "terms", "30");
  await ui.setSetting(pg_uma, "late-pct", "10.00");
  await ui.setSetting(pg_uma, "terms-B", "3");
  await ui.setSetting(pg_uma, "perm-settle", "steward");
  expect(await ui.setRole(pg_uma, "vic", "viewer")).toBe(true);
  await ui.setSetting(pg_uma, "grace-days", "0");
  expect(await ui.addHoliday(pg_uma, "2026-03-16")).toBe(true);
  await ui.setSetting(pg_uma, "grace-C", "5");
  expect(await ui.setRate(pg_uma, {"grade": "A", "pct": "5.00"})).toBe(true);
  expect(await ui.setRate(pg_uma, {"grade": "B", "pct": "10.00"})).toBe(true);
  expect(await ui.setRate(pg_uma, {"grade": "C", "pct": "12.50"})).toBe(true);
  expect(await ui.setRate(pg_uma, {"grade": "C", "pct": "33.33", "from": "2026-03-10", "to": "2026-03-12"})).toBe(true);
  expect(await ui.addPeriod(pg_uma, {"name": "P1", "from": "2026-03-01", "to": "2026-03-15"})).toBe(true);
  const p_ada = ui.must(await ui.addPerson(pg_uma, {"name": "Ada", "grade": "A"}));
  const p_ben = ui.must(await ui.addPerson(pg_uma, {"name": "Ben", "grade": "B"}));
  expect(await ui.periodAction(pg_uma, "P1", "close")).toBe(true);
  const c_ada_0 = ui.must(await ui.addClaim(pg_uma, p_ada, {"amount": "12.50", "date": "2026-03-01", "ref": " r-1 "}));
  expect(await ui.addClaim(pg_uma, p_ben, {"amount": "4.00", "date": "2026-02-10", "tags": "b,a,a"})).toBeNull();
  expect(await ui.setRate(pg_uma, {"grade": "B", "pct": "10.00"})).toBe(true);
  expect(await ui.claimAction(pg_uma, c_ada_0, "open")).toBe(true);
  expect(await ui.addProof(pg_uma, c_ada_0)).toBe(true);
  expect(await ui.statementAsOf(pg_uma, p_ada, "2026-03-09")).toBe(false);
  await ui.refresh(pg_uma);
  await expect(pg_uma.getByTestId("claim-row-" + c_ada_0).getByTestId("claim-due")).toHaveText("1.00");
  await expect(pg_uma.getByTestId("claim-row-" + c_ada_0).getByTestId("claim-status")).toHaveText("OPEN");
  await expect(pg_uma.getByTestId("claim-row-" + c_ada_0).getByTestId("claim-stated")).toHaveText("no");
  await expect(pg_uma.getByTestId("rollup-claimed-total")).toHaveText("12.50");
  await expect(pg_uma.getByTestId("rollup-due-total")).toHaveText("1.00");
  await expect(pg_uma.getByTestId("rollup-overdue-count")).toHaveText("0");
