  await expect(pg_uma.getByTestId("header-overdue-total")).toHaveText("0.00");
  expect(await ui.watch(pg_uma, p_ada, true)).toBe(true);
  expect(await ui.remind(pg_uma, c_ada_0)).toBe(true);
  const c_ada_1 = ui.must(await ui.addClaim(pg_uma, p_ada, {"amount": "4.00", "note": "n"}));
  expect(await ui.quickAdd(pg_uma, {"name": "Ben", "amount": "3.33"})).toBeNull();
  expect(await ui.editPerson(pg_uma, p_ben, {"terms": "20"})).toBe(true);
  await ui.setToday(pg_uma, "2026-03-19");
